#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// Emits docs/site/lib/generated/search-suggest-index.ts: {url,title,headings}
// per docs page, for the search dialog's typeahead (lib/search-autocomplete).
// URL derivation matches scripts/seo/link-graph.mjs exactly, so suggestion
// targets and audit edges name the same pages.
//
// Usage: node scripts/gen-search-suggest-index.mjs

import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { urlForRelPath } from "../../../scripts/seo/link-graph.mjs";

const require = createRequire(import.meta.url);
const { parseYamlFrontmatter } = require("../../../scripts/lib/parse-frontmatter.js");

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SITE_ROOT = path.resolve(HERE, "..");
const CONTENT_DIR = path.join(SITE_ROOT, "content/docs");
const OUT_FILE = path.join(SITE_ROOT, "lib/generated/search-suggest-index.ts");

function walk(dir) {
	const out = [];
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) out.push(...walk(full));
		else if (entry.name.endsWith(".mdx")) out.push(full);
	}
	return out;
}

/** Strip inline markdown/MDX from a heading line: links keep their text,
 * code/emphasis markers and JSX tags are removed. */
function cleanHeading(text) {
	return text
		.replace(/!\[[^\]]*\]\([^)]*\)/g, "")
		.replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
		.replace(/<[^>]+>/g, "")
		.replace(/[`*_~]/g, "")
		.replace(/\s+#+\s*$/, "")
		.trim();
}

/** ATX headings (h2-h6; h1 duplicates the page title) outside fenced code. */
function headingsOf(body) {
	const out = [];
	let inFence = false;
	for (const line of body.split("\n")) {
		if (/^\s*```/.test(line)) {
			inFence = !inFence;
			continue;
		}
		if (inFence) continue;
		const m = /^(#{2,6})\s+(.+)$/.exec(line);
		if (!m) continue;
		const text = cleanHeading(m[2]);
		if (text) out.push(text);
	}
	return out;
}

const files = walk(CONTENT_DIR).sort();
const entries = [];
for (const file of files) {
	const rel = path.relative(CONTENT_DIR, file);
	const raw = fs.readFileSync(file, "utf8");
	const { frontmatter, body } = parseYamlFrontmatter(raw);
	const url = urlForRelPath(rel, frontmatter.slug);
	const h1 = /^#\s+(.+)$/m.exec(body)?.[1]?.trim();
	const title = String(frontmatter.title ?? h1 ?? url);
	entries.push({ url, title, headings: headingsOf(body) });
}

const body = `// AUTO-GENERATED by docs/site/scripts/gen-search-suggest-index.mjs - do not edit.
// {url,title,headings} per docs page, for search typeahead (lib/search-autocomplete).

export type SearchSuggestEntry = { url: string; title: string; headings: string[] };

export const SEARCH_SUGGEST_INDEX: SearchSuggestEntry[] = ${JSON.stringify(entries, null, 2)};
`;

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, body);
console.log(
	`search-suggest-index: ${entries.length} pages -> ${path.relative(SITE_ROOT, OUT_FILE)}`,
);
